function scenarioFor(h){const pos=h.reasons.filter(x=>!/slab|slowing|povišen|elevated|ograničen|limited|zaduž|leverage|volatil|concentration/i.test(x)),neg=h.reasons.filter(x=>!pos.includes(x));return {bull:pos[0]||tr('profitabilnost i cash flow nadmaše trenutni trend','profitability and cash flow outperform the current trend'),base:tr('trenutni fundamentalni i valuacijski trend ostane približno stabilan','current fundamental and valuation trend remains broadly stable'),bear:neg[0]||tr('fundamentali oslabe uz nepovoljan tržišni režim','fundamentals weaken alongside an adverse market regime')}}

function correlation(a,b,days=60){const A=(a||[]).filter(x=>finite(x.c)!=null).slice(-(days+1)),B=(b||[]).filter(x=>finite(x.c)!=null).slice(-(days+1));const map=new Map(B.map(x=>[String(x.d).slice(0,10),x.c])),x=[],y=[];for(let i=1;i<A.length;i++){const d0=String(A[i-1].d).slice(0,10),d1=String(A[i].d).slice(0,10);if(!map.has(d0)||!map.has(d1))continue;const ra=A[i].c/A[i-1].c-1,rb=map.get(d1)/map.get(d0)-1;if(Number.isFinite(ra)&&Number.isFinite(rb)){x.push(ra);y.push(rb)}}if(x.length<15)return null;const mx=mean(x),my=mean(y);let num=0,dx=0,dy=0;for(let i=0;i<x.length;i++){const ax=x[i]-mx,ay=y[i]-my;num+=ax*ay;dx+=ax*ax;dy+=ay*ay}return dx>0&&dy>0?num/Math.sqrt(dx*dy):null}

function allocationStats(positions){const vals=positions.map(p=>finite(p.currentValue)).filter(v=>v!=null&&v>=0),total=sum(vals);for(const p of positions)p.weight=total>0&&Number.isFinite(p.currentValue)?p.currentValue/total*100:null;const weights=positions.map(p=>p.weight).filter(Number.isFinite).sort((a,b)=>b-a);return {total,largest:weights[0]||0,top3:sum(weights.slice(0,3)),top5:sum(weights.slice(0,5))}}
function groupWeights(holdings,key){const out={};for(const h of holdings){const k=h[key]||'Unclassified',w=finite(h.position.weight);if(w!=null)out[k]=(out[k]||0)+w}return out}

async function authenticatedFetch(local,direct){
  let r;if(typeof trading212NativeSecureV74==='function'&&trading212NativeSecureV74()){r=await fetch(local,{cache:'no-store'})}else{
    const c=(typeof trading212SessionCredsV74!=='undefined')?trading212SessionCredsV74:null;const key=c&&(c.apiKey||c.key),secret=c&&(c.apiSecret||c.secret);if(!key||!secret)throw new Error('Trading 212 credentials not configured');const token=btoa(unescape(encodeURIComponent(key+':'+secret)));r=await fetch(direct,{headers:{Authorization:`Basic ${token}`,Accept:'application/json'},cache:'no-store'})}
  if(!r.ok)throw new Error(`Trading 212 HTTP ${r.status}`);return r.json();
}
async function providerFetchJson(url,timeout=18000){if(typeof fetchWithTimeout==='function')return fetchWithTimeout(url,timeout);const ac=new AbortController(),t=setTimeout(()=>ac.abort(),timeout);try{const r=await fetch(url,{signal:ac.signal});if(!r.ok)throw new Error(`HTTP ${r.status}`);return r.json()}finally{clearTimeout(t)}}
async function validateYahoo(sym){if(!sym)return null;try{if(typeof yahoo==='function'){const s=await yahoo(sym,'1y');if(s&&s.length)return {symbol:sym,quote:null}}}catch(_){}return null}
async function resolveYahooSymbol(pos){if(symbolCache.has(pos.ticker))return symbolCache.get(pos.ticker);const candidate=t212YahooCandidate(pos.instrument);let r=await validateYahoo(candidate);if(r){symbolCache.set(pos.ticker,r);return r}
  const q=encodeURIComponent(pos.isin||pos.name||pos.shortName||candidate);try{const j=await providerFetchJson(`${SEARCH_BASE}?q=${q}&quotesCount=10&newsCount=0`,12000);const quotes=(j&&j.quotes)||[];const valid=quotes.filter(x=>['EQUITY','ETF'].includes(String(x.quoteType||'').toUpperCase())&&x.symbol);const cur=pos.currency;const best=valid.find(x=>cur&&String(x.currency||'').toUpperCase()===cur)||valid[0];if(best){r={symbol:best.symbol,quote:best};symbolCache.set(pos.ticker,r);return r}}catch(_){}
  r={symbol:candidate||'',quote:null};symbolCache.set(pos.ticker,r);return r;
}
async function loadFundamentals(sym){if(!sym)return null;const period2=Math.floor(Date.now()/1000),period1=period2-6*366*86400,url=`${FUND_BASE}${encodeURIComponent(sym)}?symbol=${encodeURIComponent(sym)}&type=${encodeURIComponent(FUND_TYPES.join(','))}&period1=${period1}&period2=${period2}`;try{return await providerFetchJson(url,20000)}catch(_){return null}}
async function marketSeries(sym){if(!sym||typeof yahoo!=='function')return null;try{return await yahoo(sym,'5y')}catch(_){return null}}
function fallbackMarketMetrics(series){if(!series||series.length<2)return {};const closes=series.map(x=>finite(x.c)).filter(Number.isFinite),last=closes[closes.length-1];const ret=n=>closes.length>n?pct(last,closes[closes.length-1-n]):null;const ma=n=>closes.length>=n?mean(closes.slice(-n)):null;const high=Math.max(...closes.slice(-Math.min(252,closes.length)));return {r1m:ret(21),r3m:ret(63),r6m:ret(126),r1y:ret(252),dist50:ma(50)?(last/ma(50)-1)*100:null,dist200:ma(200)?(last/ma(200)-1)*100:null,draw52:high>0?(last/high-1)*100:null,rv20:null,rv60:null}}
async function mapLimitLocal(items,limit,fn){let i=0;const out=new Array(items.length);async function worker(){while(i<items.length){const k=i++;try{out[k]=await fn(items[k],k)}catch(e){out[k]={error:String(e&&e.message||e)}}}}await Promise.all(Array.from({length:Math.min(limit,items.length)},worker));return out}

async function analyzeOne(pos){
  const res=await resolveYahooSymbol(pos);const sym=res.symbol;const settled=await Promise.allSettled([marketSeries(sym),loadFundamentals(sym)]);const series=settled[0].status==='fulfilled'?settled[0].value:null,payload=settled[1].status==='fulfilled'?settled[1].value:null;
  let metrics={};if(series&&series.length){try{metrics=typeof stockDetailMetrics==='function'?stockDetailMetrics(series):fallbackMarketMetrics(series)}catch(_){metrics=fallbackMarketMetrics(series)}}
  const price=pos.currentPrice||(series&&series.meta&&finite(series.meta.price))||(series&&series.length?finite(series[series.length-1].c):null);const f=payload?computeFundamentals(payload,price,series):computeFundamentals(null,price,series);
  let industry='';try{industry=(res.quote&&res.quote.industry)||((typeof companyIndustryTheme==='function'&&sym)?companyIndustryTheme(sym):'')||''}catch(_){}
  let country='';try{country=(typeof companyHomeCountry==='function'&&sym)?companyHomeCountry(sym):''}catch(_){}
  const sector=normalizedSector(pos.name,industry,pos.type),ai=aiExposure(pos.name,industry,sector);const scores={quality:scoreQuality(f),valuation:scoreValuation(f,sector),growth:scoreGrowth(f),balance:scoreBalance(f),cashFlow:scoreCashFlow(f),risk:scoreRisk(metrics),momentum:scoreMomentum(metrics),portfolioFit:null,dividend:scoreDividend(f)};
  const confidence=confidenceFor(f,!!(series&&series.length),!!pos.ticker);return {position:pos,symbol:sym||pos.ticker,name:pos.name,industry,sector,country:country||'N/A',currency:pos.currency||'N/A',series,market:metrics,fundamentals:f,scores,confidence,aiBusiness:ai,aiValuation:'N/A',macro:macroSensitivity(sector),data:{t212:Date.now(),market:series&&series.meta&&finite(series.meta.observationTimestamp)?series.meta.observationTimestamp*1000:Date.now(),fundamental:payload?Date.now():0,status:payload&&series?'LIVE':(series||payload?'PARTIAL':'PARTIAL')}};
}

function finalizeHoldings(holdings){
  const sectorW=groupWeights(holdings,'sector');for(let i=0;i<holdings.length;i++){const corrs=[];for(let j=0;j<holdings.length;j++){if(i===j)continue;const c=correlation(holdings[i].series,holdings[j].series,60);if(Number.isFinite(c))corrs.push(c)}holdings[i].avgCorr=mean(corrs);holdings[i].scores.portfolioFit=scorePortfolioFit(holdings[i].position.weight||0,sectorW[holdings[i].sector]||0,holdings[i].avgCorr);holdings[i].scores.total=totalScore(holdings[i].scores);holdings[i].status=classify(holdings[i].scores,holdings[i].confidence);holdings[i].valuationZone=valuationZone(holdings[i].scores.valuation);holdings[i].aiValuation=aiValuationRisk(holdings[i].aiBusiness,holdings[i].scores.valuation,holdings[i].fundamentals.trailingPE);holdings[i].reasons=reasonsFor(holdings[i]);holdings[i].triggers=triggersFor(holdings[i]);holdings[i].scenario=scenarioFor(holdings[i])}return holdings;
}
function portfolioSummary(holdings,account){
  const positions=holdings.map(h=>h.position),alloc=allocationStats(positions),sector=groupWeights(holdings,'sector'),country=groupWeights(holdings,'country'),currency={};for(const h of holdings){const k=h.currency||'N/A',w=h.position.weight;if(Number.isFinite(w))currency[k]=(currency[k]||0)+w}
  const aiHigh=sum(holdings.filter(h=>['HIGH','VERY HIGH'].includes(h.aiBusiness)).map(h=>finite(h.position.weight)));const avgCorr=mean(holdings.map(h=>h.avgCorr));const weighted=weightedScore(holdings.map(h=>[h.scores.total,Math.max(0.1,h.position.weight||1)]));const maxSector=Math.max(0,...Object.values(sector));const concScore=weightedScore([[interp(alloc.largest,[[0,95],[10,90],[15,75],[20,55],[30,30],[50,8]]),60],[interp(maxSector,[[0,95],[25,90],[35,72],[45,50],[60,25],[80,8]]),40]]);const diversification=interp(avgCorr,[[0,95],[0.3,88],[0.5,75],[0.7,50],[0.85,28],[1,12]]);const health=weightedScore([[weighted,75],[concScore,15],[diversification,10]]);
  const inv=account&&account.investments||{};const totalValue=finite(inv.currentValue)!=null?finite(inv.currentValue):alloc.total,totalCost=finite(inv.totalCost)!=null?finite(inv.totalCost):sum(positions.map(p=>finite(p.totalCost))),upl=finite(inv.unrealizedProfitLoss)!=null?finite(inv.unrealizedProfitLoss):sum(positions.map(p=>finite(p.unrealizedPL)));const curr=String(account&&account.currency||positions.find(p=>p.currency)&&positions.find(p=>p.currency).currency||'EUR');
  const risks=[];if(alloc.largest>15)risks.push(`${tr('Visoka pojedinačna koncentracija','High single-stock concentration')}: ${fmtPctN(alloc.largest)}`);if(alloc.top3>45)risks.push(`${tr('Top 3 koncentracija','Top-3 concentration')}: ${fmtPctN(alloc.top3)}`);if(maxSector>40){const k=Object.keys(sector).sort((a,b)=>sector[b]-sector[a])[0];risks.push(`${tr('Sektorska koncentracija','Sector concentration')}: ${k} ${fmtPctN(sector[k])}`)}if(aiHigh>40)risks.push(`${tr('Visoka AI/capex izloženost','High AI/capex exposure')}: ${fmtPctN(aiHigh)}`);if(avgCorr>0.7)risks.push(`${tr('Visoka međusobna korelacija pozicija','High cross-holding correlation')}: ${fmtN(avgCorr,2)}`);if(mean(holdings.map(h=>h.scores.valuation))<40)risks.push(tr('Portfelj je agregatno skup prema dostupnim valuacijskim metrikama','Portfolio is expensive on aggregate available valuation metrics'));
  const strengths=[];if(mean(holdings.map(h=>h.scores.quality))>=70)strengths.push(tr('Visoka prosječna kvaliteta kompanija','High average company quality'));if(mean(holdings.map(h=>h.scores.balance))>=70)strengths.push(tr('Zdrava bilanca većine pozicija','Healthy balance sheets across most positions'));if(mean(holdings.map(h=>h.scores.cashFlow))>=70)strengths.push(tr('Snažna generacija novčanog toka','Strong cash-flow generation'));if(alloc.largest<=12&&maxSector<=35)strengths.push(tr('Dobra koncentracijska disciplina','Good concentration discipline'));if(aiHigh<30)strengths.push(tr('Ograničena ovisnost o AI/capex ciklusu','Limited dependence on the AI/capex cycle'));
  return {health,totalValue,totalCost,upl,uplPct:totalCost>0?upl/totalCost*100:null,currency:curr,alloc,sector,country,currencyWeights:currency,aiHigh,avgCorr,risks:risks.length?risks:[tr('Nije identificiran dominantan portfeljni rizik iz trenutno dostupnih podataka','No dominant portfolio-level risk identified from currently available data')],strengths:strengths.length?strengths:[tr('Nema dovoljno pokrivenosti za snažan zaključak o portfeljnim prednostima','Insufficient coverage for a strong portfolio-strength conclusion')]};
}

function statusClass(s){return s==='KEEP'?'t212p-keep':s==='WATCH'?'t212p-watch':s==='REDUCE / REVIEW'?'t212p-reduce':'t212p-sell'}
function scoreCell(label,v){return `<div class="t212p-score"><span>${escP(label)}</span><b>${Number.isFinite(v)?Math.round(v):'N/A'}</b>${Number.isFinite(v)?`<i><em style="width:${clampN(v,0,100)}%"></em></i>`:''}</div>`}
function holdingCard(h,idx){const p=h.position,f=h.fundamentals||{};return `<article class="t212p-card" data-t212-holding="${idx}" tabindex="0"><div class="t212p-card-head"><div><h3>${escP(h.symbol)} <small>${escP(h.name)}</small></h3><div class="small">${escP(h.sector)} · ${escP(h.currency)}</div></div><span class="t212p-status ${statusClass(h.status)}">${escP(h.status)}</span></div><div class="t212p-position"><div><span>${tr('Vrijednost','Value')}</span><b>${fmtMoney(p.currentValue,state.portfolio&&state.portfolio.currency)}</b></div><div><span>${tr('Udio','Weight')}</span><b>${fmtPctN(p.weight)}</b></div><div><span>P/L</span><b>${fmtPctN(p.unrealizedPLPct)}</b></div><div><span>${tr('Ocjena','Score')}</span><b>${Number.isFinite(h.scores.total)?Math.round(h.scores.total):'N/A'}/100</b></div></div><div class="t212p-grid">${scoreCell(tr('Kvaliteta','Quality'),h.scores.quality)}${scoreCell(tr('Valuacija','Valuation'),h.scores.valuation)}${scoreCell(tr('Rast','Growth'),h.scores.growth)}${scoreCell(tr('Bilanca','Balance'),h.scores.balance)}${scoreCell('Cash Flow',h.scores.cashFlow)}${scoreCell(tr('Rizik','Risk'),h.scores.risk)}${scoreCell(tr('Momentum','Momentum'),h.scores.momentum)}${scoreCell(tr('Portfolio fit','Portfolio fit'),h.scores.portfolioFit)}</div><div class="t212p-meta"><span>${tr('Pouzdanost','Confidence')}: <b>${h.confidence}</b></span><span>${tr('Valuacija','Valuation')}: <b>${h.valuationZone}</b></span><span>AI: <b>${h.aiBusiness}</b></span>${f.dividendYield>0?`<span>${tr('Div. prinos','Div. yield')}: <b>${fmtPctN(f.dividendYield,2)}</b></span>`:''}</div><div class="t212p-why"><b>${tr('Zašto ovaj status?','Why this status?')}</b><ul>${h.reasons.slice(0,4).map(x=>`<li>${escP(x)}</li>`).join('')}</ul></div></article>`}

function allocationHtml(obj){const entries=Object.entries(obj||{}).sort((a,b)=>b[1]-a[1]).slice(0,8);return entries.map(([k,v])=>`<div class="t212p-alloc"><span>${escP(k)}</span><b>${fmtPctN(v)}</b><i><em style="width:${clampN(v,0,100)}%"></em></i></div>`).join('')||'<div class="small">N/A</div>'}
function filtersHtml(){const sectors=[...new Set(state.holdings.map(h=>h.sector))].sort();return `<div class="t212p-controls"><select id="t212pSort"><option value="attention" ${state.sort==='attention'?'selected':''}>${tr('ATTENTION FIRST','ATTENTION FIRST')}</option><option value="weight">${tr('Udio portfelja','Portfolio Weight')}</option><option value="value">${tr('Tržišna vrijednost','Market Value')}</option><option value="pl">P/L %</option><option value="score">${tr('Ukupna ocjena','Total Score')}</option><option value="valuation">${tr('Valuacija','Valuation Score')}</option><option value="risk">${tr('Rizik','Risk Score')}</option><option value="alpha">A–Z</option></select><select id="t212pStatus"><option value="ALL">${tr('Svi statusi','All statuses')}</option>${['KEEP','WATCH','REDUCE / REVIEW','SELL REVIEW'].map(x=>`<option ${state.filters.status===x?'selected':''}>${x}</option>`).join('')}</select><select id="t212pSector"><option value="ALL">${tr('Svi sektori','All sectors')}</option>${sectors.map(x=>`<option ${state.filters.sector===x?'selected':''}>${escP(x)}</option>`).join('')}</select><select id="t212pAi"><option value="ALL">AI: ${tr('Sve','All')}</option>${['LOW','MODERATE','HIGH','VERY HIGH'].map(x=>`<option ${state.filters.ai===x?'selected':''}>${x}</option>`).join('')}</select><select id="t212pDividend"><option value="ALL">${tr('Dividenda: sve','Dividend: all')}</option><option value="YES" ${state.filters.dividend==='YES'?'selected':''}>${tr('Plaća dividendu','Dividend payer')}</option><option value="NO" ${state.filters.dividend==='NO'?'selected':''}>${tr('Bez dividende','No dividend')}</option></select></div>`}
function filteredSorted(){let a=state.holdings.slice().filter(h=>state.filters.status==='ALL'||h.status===state.filters.status).filter(h=>state.filters.sector==='ALL'||h.sector===state.filters.sector).filter(h=>state.filters.ai==='ALL'||h.aiBusiness===state.filters.ai).filter(h=>state.filters.dividend==='ALL'||(state.filters.dividend==='YES'?(h.fundamentals.dividendYield>0):!(h.fundamentals.dividendYield>0)));const n=(v,d=-Infinity)=>Number.isFinite(v)?v:d;if(state.sort==='attention')a.sort((x,y)=>(STATUS_ORDER[x.status]-STATUS_ORDER[y.status])||n(x.scores.total)-n(y.scores.total));else if(state.sort==='weight')a.sort((x,y)=>n(y.position.weight)-n(x.position.weight));else if(state.sort==='value')a.sort((x,y)=>n(y.position.currentValue)-n(x.position.currentValue));else if(state.sort==='pl')a.sort((x,y)=>n(y.position.unrealizedPLPct)-n(x.position.unrealizedPLPct));else if(state.sort==='score')a.sort((x,y)=>n(y.scores.total)-n(x.scores.total));else if(state.sort==='valuation')a.sort((x,y)=>n(y.scores.valuation)-n(x.scores.valuation));else if(state.sort==='risk')a.sort((x,y)=>n(x.scores.risk)-n(y.scores.risk));else a.sort((x,y)=>x.name.localeCompare(y.name));return a}

function render(){const root=document.getElementById('t212PortfolioContent');if(!root)return;if(state.status==='loading'){const pct=state.progressTotal?state.progressDone/state.progressTotal*100:5;root.innerHTML=`<div class="panel"><div class="t212p-loading"><b>${tr('Učitavanje My T212 Portfolio analize','Loading My T212 Portfolio analysis')}</b><div>${escP(state.progressDone)} / ${escP(state.progressTotal||'—')} ${tr('pozicija','holdings')}</div><i><em style="width:${clampN(pct,2,100)}%"></em></i><div class="small">${tr('Trading 212 pozicije → tržišni podaci → fundamenti → scoring. Jedan neuspjeli izvor ne blokira ostatak.','Trading 212 positions → market data → fundamentals → scoring. One failing source does not block the rest.')}</div></div></div>`;return}
  if(state.status==='error'){root.innerHTML=`<div class="panel t212p-empty"><h3>${tr('T212 portfelj nije dostupan','T212 portfolio unavailable')}</h3><p>${escP(state.error)}</p><div class="setting-actions"><button class="seg" data-t212p-retry>${tr('POKUŠAJ PONOVNO','RETRY')}</button><button class="seg" data-t212p-settings>${tr('OTVORI SETTINGS','OPEN SETTINGS')}</button></div></div>`;return}
  if(state.status==='empty'){root.innerHTML=`<div class="panel t212p-empty"><h3>${tr('Nema otvorenih Trading 212 pozicija','No open Trading 212 positions')}</h3><p>${tr('API je dostupan, ali /equity/positions nije vratio otvorene pozicije.','The API is available, but /equity/positions returned no open holdings.')}</p></div>`;return}
  if(state.status!=='ready'){root.innerHTML=`<div class="panel t212p-empty"><h3>My T212 Portfolio</h3><p>${tr('Otvaranje kartice učitava stvarne read-only pozicije iz Trading 212 API-ja i analizira ih bez slanja naloga.','Opening this tab loads actual read-only positions from the Trading 212 API and analyzes them without placing orders.')}</p><button class="seg" data-t212p-retry>${tr('UČITAJ PORTFELJ','LOAD PORTFOLIO')}</button></div>`;return}
  const p=state.portfolio,visible=filteredSorted();root.innerHTML=`<div class="t212p-overview panel"><div class="t212p-overview-head"><div><span class="small">${tr('PORTFOLIO HEALTH SCORE','PORTFOLIO HEALTH SCORE')}</span><strong>${Number.isFinite(p.health)?Math.round(p.health):'N/A'}<small>/100</small></strong></div><div class="t212p-live"><b>${state.sourceStatus}</b><span>${new Date(state.updatedAt).toLocaleString()}</span></div></div><div class="t212p-kpis"><div><span>${tr('Vrijednost','Value')}</span><b>${fmtMoney(p.totalValue,p.currency)}</b></div><div><span>${tr('Uloženo','Invested')}</span><b>${fmtMoney(p.totalCost,p.currency)}</b></div><div><span>${tr('Nerealizirani P/L','Unrealized P/L')}</span><b>${fmtMoney(p.upl,p.currency)} · ${fmtPctN(p.uplPct)}</b></div><div><span>${tr('Pozicije','Holdings')}</span><b>${state.holdings.length}</b></div><div><span>${tr('Najveća pozicija','Largest position')}</span><b>${fmtPctN(p.alloc.largest)}</b></div><div><span>Top 3</span><b>${fmtPctN(p.alloc.top3)}</b></div><div><span>Top 5</span><b>${fmtPctN(p.alloc.top5)}</b></div><div><span>AI/capex</span><b>${fmtPctN(p.aiHigh)}</b></div></div></div><div class="t212p-two"><div class="panel"><h3>${tr('Ključni rizici portfelja','Key portfolio risks')}</h3><ul>${p.risks.map(x=>`<li>${escP(x)}</li>`).join('')}</ul></div><div class="panel"><h3>${tr('Prednosti portfelja','Portfolio strengths')}</h3><ul>${p.strengths.map(x=>`<li>${escP(x)}</li>`).join('')}</ul></div></div><div class="t212p-two"><div class="panel"><h3>${tr('Sektorska alokacija','Sector allocation')}</h3>${allocationHtml(p.sector)}</div><div class="panel"><h3>${tr('Valutna izloženost','Currency exposure')}</h3>${allocationHtml(p.currencyWeights)}</div></div>${filtersHtml()}<div class="small t212p-note">${tr('Status procjenjuje današnji risk/reward iz dostupnih tržišnih i fundamentalnih podataka. Kupovna cijena i postojeći P/L prikazuju se informativno, ali ne određuju KEEP/SELL status.','Status evaluates today’s risk/reward from available market and fundamental data. Purchase price and existing P/L are displayed for context but do not determine KEEP/SELL status.')}</div><div class="t212p-list">${visible.map((h)=>holdingCard(h,state.holdings.indexOf(h))).join('')}</div>`;
  bindControls();
}
function bindControls(){const map=[['t212pSort','sort'],['t212pStatus','status'],['t212pSector','sector'],['t212pAi','ai'],['t212pDividend','dividend']];for(const [id,k] of map){const e=document.getElementById(id);if(!e)continue;e.onchange=()=>{if(k==='sort')state.sort=e.value;else state.filters[k]=e.value;render()}}}

function metricRow(label,value){return `<div class="t212p-detail-row"><span>${escP(label)}</span><b>${escP(value)}</b></div>`}
function openDetail(idx){const h=state.holdings[Number(idx)];if(!h)return;const modal=document.getElementById('stockModal'),title=document.getElementById('stockModalTitle'),body=document.getElementById('stockModalBody');if(!modal||!body)return;const p=h.position,f=h.fundamentals,m=h.market;title.textContent=`${h.symbol} — ${h.name}`;body.innerHTML=`<div class="t212p-detail"><div class="t212p-detail-hero"><span class="t212p-status ${statusClass(h.status)}">${h.status}</span><strong>${Number.isFinite(h.scores.total)?Math.round(h.scores.total):'N/A'}/100</strong><div>${tr('Pouzdanost','Confidence')}: <b>${h.confidence}</b></div></div><h3>${tr('Pozicija','Position')}</h3>${metricRow(tr('Količina','Quantity'),fmtN(p.quantity,6))}${metricRow(tr('Prosječna kupovna cijena','Average purchase price'),fmtMoney(p.averagePrice,p.currency))}${metricRow(tr('Trenutna cijena','Current price'),fmtMoney(p.currentPrice,p.currency))}${metricRow(tr('Tržišna vrijednost','Market value'),fmtMoney(p.currentValue,state.portfolio.currency))}${metricRow(tr('Udio portfelja','Portfolio weight'),fmtPctN(p.weight))}${metricRow('P/L',`${fmtMoney(p.unrealizedPL,state.portfolio.currency)} · ${fmtPctN(p.unrealizedPLPct)}`)}<h3>${tr('Analitičke ocjene','Analytical scores')}</h3><div class="t212p-grid">${scoreCell(tr('Kvaliteta','Quality'),h.scores.quality)}${scoreCell(tr('Valuacija','Valuation'),h.scores.valuation)}${scoreCell(tr('Rast','Growth'),h.scores.growth)}${scoreCell(tr('Bilanca','Balance'),h.scores.balance)}${scoreCell('Cash Flow',h.scores.cashFlow)}${scoreCell(tr('Rizik','Risk'),h.scores.risk)}${scoreCell(tr('Momentum','Momentum'),h.scores.momentum)}${scoreCell(tr('Portfolio fit','Portfolio fit'),h.scores.portfolioFit)}</div><h3>${tr('Fundamentali i valuacija','Fundamentals & valuation')}</h3>${metricRow('P/E',Number.isFinite(f.trailingPE)?`${fmtN(f.trailingPE,1)}x`:'N/A')}${metricRow('P/S',Number.isFinite(f.priceToSales)?`${fmtN(f.priceToSales,1)}x`:'N/A')}${metricRow('P/B',Number.isFinite(f.priceToBook)?`${fmtN(f.priceToBook,1)}x`:'N/A')}${metricRow('EV/EBITDA',Number.isFinite(f.evToEbitda)?`${fmtN(f.evToEbitda,1)}x`:'N/A')}${metricRow('FCF yield',fmtPctN(f.fcfYield))}${metricRow(tr('Rast prihoda YoY','Revenue growth YoY'),fmtPctN(f.revenueGrowth))}${metricRow(tr('Rast EPS YoY','EPS growth YoY'),fmtPctN(f.epsGrowth))}${metricRow('ROIC',fmtPctN(f.roic))}${metricRow('ROE',fmtPctN(f.roe))}${metricRow(tr('Operativna marža','Operating margin'),fmtPctN(f.operatingMargin))}${metricRow('FCF margin',fmtPctN(f.fcfMargin))}${metricRow('Debt/Equity',Number.isFinite(f.debtToEquity)?fmtN(f.debtToEquity,2):'N/A')}${metricRow('Debt/FCF',Number.isFinite(f.debtToFcf)?`${fmtN(f.debtToFcf,1)}x`:'N/A')}${metricRow(tr('Dividendni prinos','Dividend yield'),fmtPctN(f.dividendYield,2))}<h3>${tr('Tržišni rizik i trend','Market risk & trend')}</h3>${metricRow('1M',fmtPctN(m.r1m))}${metricRow('3M',fmtPctN(m.r3m))}${metricRow('6M',fmtPctN(m.r6m))}${metricRow('1Y',fmtPctN(m.r1y))}${metricRow('vs 200DMA',fmtPctN(m.dist200))}${metricRow('52W drawdown',fmtPctN(m.draw52))}${metricRow('RV20',fmtPctN(m.rv20))}${metricRow('RV60',fmtPctN(m.rv60))}<h3>AI / CAPEX</h3>${metricRow(tr('Poslovna izloženost','Business exposure'),h.aiBusiness)}${metricRow(tr('Valuacijski rizik','Valuation exposure'),h.aiValuation)}${metricRow(tr('Makro osjetljivost','Macro sensitivity'),h.macro.join(' · '))}<h3>${tr('Zašto ovaj status?','Why this status?')}</h3><ul>${h.reasons.map(x=>`<li>${escP(x)}</li>`).join('')}</ul><div class="t212p-scenarios"><div><b>BULL</b><p>${escP(h.scenario.bull)}</p></div><div><b>BASE</b><p>${escP(h.scenario.base)}</p></div><div><b>BEAR</b><p>${escP(h.scenario.bear)}</p></div></div><h3>${tr('Što bi promijenilo procjenu?','What would change the view?')}</h3><ul>${h.triggers.map(x=>`<li>${escP(x)}</li>`).join('')}</ul><h3>${tr('Izvori i svježina','Sources & freshness')}</h3>${metricRow('Trading 212',`${ageLabel(h.data.t212)} · /equity/positions`)}${metricRow('Market data',`${ageLabel(h.data.market)} · Yahoo Finance chart`)}${metricRow('Fundamentals',h.data.fundamental?`${ageLabel(h.data.fundamental)} · Yahoo Finance fundamentals-timeseries`:'PARTIAL / N/A')}<div class="small t212p-note">${tr('Analiza je informativna i nije nalog za trgovanje. Nedostajući podaci se ne pretvaraju u nulu; preostale komponente se normaliziraju.','Analysis is informational and is not a trading order. Missing data are not converted to zero; remaining components are normalized.')}</div></div>`;modal.classList.add('show');
}

async function loadPortfolio(force){if(state.status==='loading')return;if(!force&&state.status==='ready')return;let configured=false;try{configured=typeof trading212ConfiguredV74==='function'&&trading212ConfiguredV74()}catch(_){}if(!configured){state.status='error';state.error=tr('Trading 212 API credentials nisu konfigurirani. Otvori Settings i spremi read-only API key/secret.','Trading 212 API credentials are not configured. Open Settings and save a read-only API key/secret.');render();return}
  state.status='loading';state.error='';state.progressDone=0;state.progressTotal=0;render();try{const pair=await Promise.allSettled([authenticatedFetch(POSITIONS_LOCAL,POSITIONS_DIRECT),authenticatedFetch(ACCOUNT_LOCAL,ACCOUNT_DIRECT)]);if(pair[0].status!=='fulfilled')throw pair[0].reason;const raw=Array.isArray(pair[0].value)?pair[0].value:(pair[0].value&&pair[0].value.items)||[];state.account=pair[1].status==='fulfilled'?pair[1].value:null;state.positions=raw.map(normalizePosition).filter(p=>p.ticker&&((p.quantity||0)>0||(p.currentValue||0)>0));if(!state.positions.length){state.status='empty';state.updatedAt=Date.now();state.sourceStatus='LIVE';render();return}allocationStats(state.positions);state.progressTotal=state.positions.length;const holdings=await mapLimitLocal(state.positions,4,async(pos)=>{const h=await analyzeOne(pos);state.progressDone++;render();return h});state.holdings=finalizeHoldings(holdings.filter(h=>h&&h.position));state.portfolio=portfolioSummary(state.holdings,state.account);state.updatedAt=Date.now();state.sourceStatus=pair[1].status==='fulfilled'?'LIVE':'PARTIAL';state.status='ready';render()}catch(e){state.status='error';state.error=String(e&&e.message||e||'Unknown error');state.sourceStatus='N/A';render()}}

